export function applyReviewedCatalogueBatch06(byId: Map<string, Article>): void {
  for (const entry of REVIEWED_CATALOGUE_BATCH_06_TAGS) {
    const article = byId.get(entry.articleId);
    if (article && JSON.stringify(article.tags) === JSON.stringify(entry.previousTags)) article.tags = [...entry.tags];
  }
  applyContextualLinks(byId, REVIEWED_CATALOGUE_BATCH_06_LINKS);
}
